const pendingSessions = ref([]);
const pendingLoading = ref(false);
const pendingMarkStatus = ref({});
const pendingMarkSubmitting = ref({});
const pendingMarkMsg = ref('');
const pendingMarkMsgType = ref('');
const todaySessionTotal = ref(0);
